#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string num;
    cin >> num;
    long long k;
    cin >> k;

    string stack;
    for (char d : num) {
        while (k > 0 && !stack.empty() && stack.back() > d) {
            stack.pop_back();
            k--;
        }
        stack += d;
    }
    if (k > 0) stack.erase(stack.size() - k);
    size_t start = 0;
    while (start < stack.size() && stack[start] == '0') start++;
    string result = stack.substr(start);
    cout << (result.empty() ? "0" : result) << "\n";

    return 0;
}

